-- settings.bind (native, DMS has no equivalent)
hl.bind((mod .. ' + Q'), (hl.dsp.window.close()), { ['locked'] = true })
hl.bind(
  (mod .. ' + SHIFT + F'),
  (hl.dsp.window.fullscreen({ mode = 'fullscreen', action = 'toggle' }))
)
hl.bind(
  (mod .. ' + F'),
  (hl.dsp.window.fullscreen({ mode = 'maximized', action = 'toggle' }))
)
hl.bind((mod .. ' + RETURN'), (hl.dsp.exec_cmd('runapp xdg-terminal-exec')))
hl.bind((mod .. ' + E'), (hl.dsp.exec_cmd('dolphin')))
