hl.bind((mod .. ' + P'), (hl.dsp.window.pseudo()))
hl.bind(
  (mod .. ' + SHIFT + M'),
  (
    hl.dsp.exec_cmd(
      "command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"
    )
  )
) -- moved off mod+M, see DMS processlist below
